(671, 1, '2025-02-25 20:04:22', '2025-02-25 19:04:22', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:spacer {\"height\":\"53px\"} -->\n<div style=\"height:53px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Dernières publications</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:latest-posts {\"postLayout\":\"grid\"} /--></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Atlas</h2>\n<!-- /wp:heading -->\n\n<!-- wp:image {\"id\":646,\"sizeSlug\":\"large\",\"linkDestination\":\"none\"} -->\n<figure class=\"wp-block-image size-large\"><img src=\"http://localhost/DicoTrav/wp-content/uploads/2025/02/Western_Europe_map.svg\" alt=\"\" class=\"wp-image-646\"/><figcaption class=\"wp-element-caption\">Atlas...</figcaption></figure>\n<!-- /wp:image -->\n\n<!-- wp:spacer -->\n<div style=\"height:100px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading -->\n<h2 class=\"wp-block-heading\">                               Timeline</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"15px\"} -->\n<div style=\"height:15px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:html -->\n<!DOCTYPE html>\n<html lang=\"fr\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Timeline Histoire</title>\n    <style>\n       .timeline {\n            position: relative;\n            max-width: 600px;\n            margin: auto;\n        }\n\n        .timeline::after {\n            content: \'\';\n            position: absolute;\n            width: 4px;\n            background-color: #333;\n            top: 0;\n            bottom: 0;\n            left: 50%;\n            transform: translateX(-50%);\n        }\n\n        .timeline-item {\n            position: relative;\n            background-color: inherit;\n            width: 50%;\n            padding: 10px 20px;\n            box-sizing: border-box;\n        }\n\n        .timeline-item:nth-child(odd) {\n            left: 0;\n            text-align: right;\n        }\n\n        .timeline-item:nth-child(even) {\n            left: 50%;\n        }\n\n        .timeline-content {\n            background: #fff;\n            padding: 15px;\n            border-radius: 5px;\n            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);\n            position: relative;\n            margin-bottom: 50px;\n        }\n\n        .timeline-item::before {\n            content: \'\';\n            position: absolute;\n            top: 15px;\n            width: 20px;\n            height: 20px;\n            background-color: #333;\n            border-radius: 50%;\n            left: 50%;\n            transform: translateX(-50%);\n        }\n\n        h2 {\n            font-size: 18px;\n            margin-bottom: 8px;\n        }\n        .contempo{\n            font-size: 16px;\n        }\n    </style>\n</head>\n<body>\n    <div class=\"timeline\">\n        <div class=\"timeline-item\">\n            <div class=\"timeline-content\">\n                <h2>Moyen Âge</h2>\n                <p>Période allant du Ve siècle au XVe siècle.</p>\n            </div>\n        </div>\n        <div class=\"timeline-item\">\n            <div class=\"timeline-content\">\n                <h2>Époque Moderne</h2>\n                <p>Période allant du XVIe au XVIIIe siècle.</p>\n            </div>\n        </div>\n        <div class=\"timeline-item\">\n            <div class=\"timeline-content\">\n                <h2 class=\"contempo\">Époque <br> <br> Contemporaine</h2>\n                <p>Période allant du XIXe siècle à nos jours.</p>\n            </div>\n        </div>\n    </div>\n</body>\n</html>\n<!-- /wp:html --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Loop', '', 'inherit', 'closed', 'closed', '', '459-revision-v1', '', '', '2025-02-25 20:04:22', '2025-02-25 19:04:22', '', 459, 'http://localhost/DicoTrav/?p=671', 0, 'revision', '', 0),
