(548, 1, '2025-02-05 16:22:46', '2025-02-05 15:22:46', '<!-- wp:group {\"backgroundColor\":\"custom-brown\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group has-custom-brown-background-color has-background\"><!-- wp:site-logo {\"width\":96,\"shouldSyncIcon\":true,\"className\":\"is-style-rounded\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}}} /-->\n\n<!-- wp:search {\"label\":\"\",\"showLabel\":false,\"placeholder\":\"Rechercher...\",\"buttonText\":\"Rechercher\",\"buttonUseIcon\":true,\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}}}} /-->\n\n<!-- wp:loginout {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-light-pink\"},\":hover\":{\"color\":{\"text\":\"var:preset|color|custom-mid-brown\"}}}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}}}} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"}}},\"backgroundColor\":\"custom-red\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-custom-red-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\"}},\"dimensions\":{\"minHeight\":\"52px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"min-height:52px;padding-top:0;padding-bottom:0\"><!-- wp:navigation {\"ref\":5,\"textColor\":\"custom-light-pink\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"flexWrap\":\"wrap\"}} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:html -->\n<!-- Sidebar -->\n<div id=\"sidebar\">\n    <button id=\"closeSidebar\" class=\"sidebar-close\">&times;</button>\n    <nav>\n        <ul>\n            <?php\n            // Générer dynamiquement la liste des catégories\n            $categories = get_categories();\n            foreach ($categories as $category) {\n                echo \'<li><a href=\"\' . get_category_link($category->term_id) . \'\">\' . $category->name . \'</a></li>\';\n            }\n            ?>\n        </ul>\n    </nav>\n</div>\n\n<!-- Overlay pour le mobile -->\n<div id=\"sidebarOverlay\"></div>\n\n<!-- Bouton pour ouvrir la sidebar -->\n<button id=\"openSidebar\" class=\"sidebar-toggle\">&#9776;</button>\n\n<!-- Style (CSS inline ou lien externe) -->\n<style>\n    body.sidebar-open #sidebar {\n        transform: translateX(0);\n    }\n    body.sidebar-open #sidebarOverlay {\n        display: block;\n    }\n    #sidebar {\n        position: fixed;\n        top: 0;\n        left: 0;\n        height: 100%;\n        width: 250px;\n        background: #111;\n        color: #fff;\n        transform: translateX(-100%);\n        transition: transform 0.3s ease;\n    }\n    #sidebar nav ul {\n        list-style: none;\n        padding: 0;\n    }\n    #sidebar nav ul li {\n        margin: 1rem 0;\n        text-align: center;\n    }\n    #sidebar nav ul li a {\n        color: #fff;\n        text-decoration: none;\n    }\n    #sidebarOverlay {\n        display: none;\n        position: fixed;\n        top: 0;\n        left: 0;\n        width: 100%;\n        height: 100%;\n        background: rgba(0, 0, 0, 0.5);\n        z-index: 100;\n    }\n    .sidebar-toggle {\n        position: fixed;\n        top: 10px;\n        left: 10px;\n        z-index: 101;\n        background: #111;\n        color: #fff;\n        border: none;\n        padding: 10px 15px;\n        cursor: pointer;\n    }\n    .sidebar-close {\n        position: absolute;\n        top: 10px;\n        right: 10px;\n        background: none;\n        border: none;\n        color: #fff;\n        font-size: 1.5rem;\n        cursor: pointer;\n    }\n</style>\n\n<!-- Script -->\n<script>\ndocument.addEventListener(\"DOMContentLoaded\", function() {\n    var openBtn = document.getElementById(\"openSidebar\");\n    var closeBtn = document.getElementById(\"closeSidebar\");\n    var sidebar = document.getElementById(\"sidebar\");\n    var overlay = document.getElementById(\"sidebarOverlay\");\n    var body = document.body;\n\n    function toggleSidebar() {\n        body.classList.toggle(\"sidebar-open\");\n    }\n\n    openBtn.addEventListener(\"click\", toggleSidebar);\n    closeBtn.addEventListener(\"click\", toggleSidebar);\n    overlay.addEventListener(\"click\", toggleSidebar);\n});\n</script>\n\n<!-- /wp:html --></div>\n<!-- /wp:group -->', 'Header', '', 'inherit', 'closed', 'closed', '', '430-revision-v1', '', '', '2025-02-05 16:22:46', '2025-02-05 15:22:46', '', 430, 'http://localhost/DicoTrav/?p=548', 0, 'revision', '', 0),
