ne;\\n    width: 100%;\\n    max-width: 300px;\\n  }\\n  .wp-block-search__input:focus {\\n    width: 350px;\\n    max-width: 350px;\\n    border-color: #D4A373;\\n    box-shadow: 0 0 12px rgba(212, 163, 115, 0.8);\\n  }\\n  \\n  .wp-block-search__button {\\n    background-color: #D4A373;\\n    border-radius: 50%;\\n    padding: 15px;\\n    border: none;\\n    transition: transform 0.2s ease-in-out, box-shadow 0.2s ease-in-out;\\n  }\\n  .wp-block-search__button:hover {\\n    transform: scale(1.1);\\n    box-shadow: 0 0 8px rgba(212, 163, 115, 0.8);\\n  }\\n  .wp-block-search__button svg {\\n    transition: transform 0.2s ease-in-out;\\n    fill: #F7F1EB;\\n  }\\n  .wp-block-search__input:focus + .wp-block-search__button svg {\\n    transform: rotate(15deg);\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*      Traduction (TRP Floater)      *\\/\\n  \\/* ===================== *\\/\\n  \\n  #trp-floater-ls.trp-bottom-right {\\n    right: 10px !important;\\n    bottom: 10px !important;\\n    border-radius: 5px !important;\\n    background: #D4A373!important;\\n    transition: transform 0.2s ease;\\n    cursor: pointer;\\n    z-index: 999;\\n  }\\n  #trp-floater-ls-current-language a {\\n    margin: 10px 0 !important;\\n  }\\n  #trp-floater-ls-language-list .trp-language-wrap a {\\n    margin: 10px !important;\\n  }\\n  #trp-floater-ls.trp-bottom-right:hover {\\n    transform: scale(1.05);\\n  }\\n  #trp-floater-ls a {\\n    color: #29354C !important;\\n    text-decoration: none;\\n    font-size: 12px;\\n    padding: 3px 5px;\\n    display: inline-block;\\n  }\\n  #trp-floater-ls.trp-floater-ls-codes #trp-floater-ls-language-list {\\n    margin-top: 0 !important;\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*        Responsive (max-width: 768px)        *\\/\\n  \\/* ===================== *\\/\\n  \\n  @media screen and (max-width: 768px) {\\n    \\/* R\\u00e9organisation du conteneur global des ic\\u00f4nes et du formulaire *\\/\\n    .wp-container-core-group-is-layout-17 {\\n      flex-direction: column !important;\\n      align-items: center;\\n      gap: 20px;\\n      justify-items: center;\\n    }\\n\\n    .wp-container-core-group-is-layout-18 {\\n      flex-wrap: wrap !important;\\n      justify-content: center !important;\\n      align-items: center;\\n      justify-items: center;\\n    }\\n\\n    .wp-container-core-group-is-layout-16 {\\n      flex-wrap: wrap !important;\\n      justify-content: center !important;\\n      align-items: center;\\n      justify-items: center;\\n    }\\n    \\/* Ic\\u00f4nes de partage en premier *\\/\\n    .wp-container-core-group-is-layout-17 > .wp-block-group.is-layout-flex {\\n      order: 1;\\n      width: 100%;\\n      text-align: center;\\n    }\\n    \\/* Formulaire en deuxi\\u00e8me *\\/\\n    .wp-container-core-group-is-layout-17 > .wpforms-container {\\n      order: 2;\\n      width: 100%;\\n      text-align: center;\\n    }\\n    \\/* Centrage du champ d\'email *\\/\\n    #wpforms-190-field_2 {\\n      margin: 0 auto;\\n      text-align: center;\\n    }\\n\\n    .form-newletters .wpforms-field {\\n        display: inline-flex !important;\\n        align-items: flex-end;\\n    }\\n\\n    .wpforms-field-email{\\n        flex-direction: column !important;\\n        display: flex !important;\\n        align-items: flex-start !important;\\n    }\\n  }\\n  \\n  \\/* ===================== *\\/\\n  \\/*        Formulaire : R\\u00e9duction du padding dans le header du formulaire        *\\/\\n  \\/* ===================== *\\/\\n  \\n  .wpforms-head-container {\\n    padding: 0px !important; \\/* Ajuste selon tes besoins *\\/\\n  }\\n  \\n  .form-newletters .wpforms-field {\\n    display: flex !important;\\n    align-items: flex-end;\\n}\\n\\n.wpforms-submit{\\n    background-color: #3c5075 !important;\\n    color: #F7F1EB !important;\\n    border-radius: 10px;\\n    border: none !important;\\n    transition: background-color 0.3s, color 0.2s !important;\\n    font-weight: bold !important;\\n}\\n  \\n\\/* Effet hover pour le lien actif et les boutons *\\/\\n.wpforms-submit:hover{\\n    background-color: #D4A373 !important;\\n    color: #29354C !important;\\n}\\n\\n.wpforms-field-label {\\n    display: inline-flex !important;\\n    margin-right: 10px !important;\\n}\"},\"settings\":{\"typography\":{\"fontFamilies\":{\"theme\":[],\"custom\":[{\"name\":\"EB Garamond\",\"slug\":\"eb-garamond\",\"fontFamily\":\"\\\"EB Garamond\\\", serif\",\"fontFace\":[{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-6_RUBoV-e6yHgQ.woff2\",\"fontWeight\":\"400\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-2fRUBoV-e6yHgQ.woff2\",\"fontWeight\":\"500\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-NfNUBoV-e6yHgQ.woff2\",\"fontWeight\":\"600\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-DPNUBoV-e6yHgQ.woff2\",\"fontWeight\":\"700\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGDmQSNjdsmc35JDF1K5E55YMjF_7DPuGi-a_NUBoV-e6yHgQ.woff2\",\"fontWeight\":\"800\",\"fontStyle\":\"normal\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7e8QI9_WamXgXFI.woff2\",\"fontWeight\":\"400\",\"fontStyle\":\"italic\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7eOQI9_WamXgXFI.woff2\",\"fontWeight\":\"500\",\"fontStyle\":\"italic\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7diR49_WamXgXFI.woff2\",\"fontWeight\":\"600\",\"fontStyle\":\"italic\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7dbR49_WamXgXFI.woff2\",\"fontWeight\":\"700\",\"fontStyle\":\"italic\",\"fontFamily\":\"\\\"EB Garamond\\\"\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/SlGFmQSNjdsmc35JDF1K5GRwUjcdlttVFm-rI7c8R49_WamXgXFI.woff2\",\"fontWeight\":\"800\",\"fontStyle\":\"italic\",\"fontFamily\":\"\\\"EB Garamond\\\"\"}]},{\"name\":\"Roboto\",\"slug\":\"roboto\",\"fontFamily\":\"Roboto, sans-serif\",\"fontFace\":[{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/KFOkCnqEu92Fr1MmgWxKKTM1K9nz.woff2\",\"fontWeight\":\"100\",\"fontStyle\":\"normal\",\"fontFamily\":\"Roboto\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/KFOlCnqEu92Fr1MmSU5vBh05IsDqlA.woff2\",\"fontWeight\":\"300\",\"fontStyle\":\"normal\",\"fontFamily\":\"Roboto\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/KFOmCnqEu92Fr1Me4GZLCzYlKw.woff2\",\"fontWeight\":\"400\",\"fontStyle\":\"normal\",\"fontFamily\":\"Roboto\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/KFOlCnqEu92Fr1MmEU9vBh05IsDqlA.woff2\",\"fontWeight\":\"500\",\"fontStyle\":\"normal\",\"fontFamily\":\"Roboto\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/KFOlCnqEu92Fr1MmWUlvBh05IsDqlA.woff2\",\"fontWeight\":\"700\",\"fontStyle\":\"normal\",\"fontFamily\":\"Roboto\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fonts\\/KFOlCnqEu92Fr1MmYUtvBh05IsDqlA.woff2\",\"fontWeight\":\"900\",\"fontStyle\":\"normal\",\"fontFamily\":\"Roboto\"},{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-