om-mid-brown-background-color has-background\" style=\"min-height:48px;margin-top:0;margin-bottom:0\"><!-- wp:group {\"align\":\"wide\",\"style\":{\"spacing\":{\"padding\":{\"top\":\"var:preset|spacing|20\",\"bottom\":\"var:preset|spacing|20\"}},\"dimensions\":{\"minHeight\":\"52px\"}},\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\",\"verticalAlignment\":\"center\"}} -->\n<div class=\"wp-block-group alignwide\" style=\"min-height:52px;padding-top:var(--wp--preset--spacing--20);padding-bottom:var(--wp--preset--spacing--20)\"><!-- wp:navigation {\"ref\":117,\"overlayMenu\":\"never\"} /-->\n\n<!-- wp:paragraph -->\n<p>@2025 DicoTrav - Réalisation du site : Agence MFK</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:navigation {\"ref\":249,\"overlayMenu\":\"never\"} /--></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<script>\ndocument.addEventListener(\'DOMContentLoaded\', function() {\n    // Fonction pour récupérer la valeur d\'un cookie par son nom\n    function getCookieValue(name) {\n        var value = \"; \" + document.cookie;\n        var parts = value.split(\"; \" + name + \"=\");\n        if(parts.length === 2) return parts.pop().split(\";\").shift();\n        return null;\n    }\n\n    // Fonction pour créer ou mettre à jour un cookie\n    function setCookie(name, value, days) {\n        var expires = \"\";\n        if (days) {\n            var date = new Date();\n            date.setTime(date.getTime() + (days*24*60*60*1000));\n            expires = \"; expires=\" + date.toUTCString();\n        }\n        document.cookie = name + \"=\" + (value || \"\")  + expires + \"; path=/\";\n    }\n\n    // Vérifier si le cookie \"trp_language\" existe, sinon le créer avec la valeur \"fr\" par défaut\n    var lang = getCookieValue(\'trp_language\');\n    if (!lang) {\n        setCookie(\'trp_language\', \'fr\', 30); // Définit le cookie pour 30 jours\n        lang = \'fr\';\n    }\n\n    // Si le cookie indique l\'italien, et que l\'URL ne commence pas déjà par \"/it\", rediriger\n    if (lang === \'it\') {\n        var pathname = window.location.pathname;\n        if (!pathname.match(/^\\/it(\\/|$)/)) {\n            var newUrl = window.location.origin + \'/it\' + pathname + window.location.search + window.location.hash;\n            window.location.href = newUrl;\n        }\n    }\n});\n</script>', 'Footer', '', 'inherit', 'closed', 'closed', '', '492-revision-v1', '', '', '2025-04-03 17:40:26', '2025-04-03 15:40:26', '', 492, 'http://localhost/DicoTrav/?p=1480', 0, 'revision', '', 0),
