slug\":\"custom-light-pink\"},{\"color\":\"#d4a373\",\"name\":\"Red\",\"slug\":\"custom-red\"},{\"color\":\"#3c5075\",\"name\":\"Mid Brown\",\"slug\":\"custom-mid-brown\"}]}},\"shadow\":{\"presets\":{\"default\":[{\"name\":\"Natural\",\"slug\":\"natural\",\"shadow\":\"6px 6px 9px rgba(0, 0, 0, 0.2)\"},{\"name\":\"Deep\",\"slug\":\"deep\",\"shadow\":\"12px 12px 50px rgba(0, 0, 0, 0.4)\"},{\"name\":\"Sharp\",\"slug\":\"sharp\",\"shadow\":\"6px 6px 9px rgba(0, 0, 0, 0.2)\"},{\"name\":\"Outlined\",\"slug\":\"outlined\",\"shadow\":\"6px 6px 0px -3px rgba(255, 255, 255, 1), 6px 6px rgba(0, 0, 0, 1)\"},{\"name\":\"Crisp\",\"slug\":\"crisp\",\"shadow\":\"6px 6px 9px rgba(0, 0, 0, 0.2)\"}],\"custom\":[{\"name\":\"Ombre 1\",\"shadow\":\"6px 6px 9px 0 #00000080\",\"slug\":\"shadow-1\"}]}}},\"isGlobalStylesUserThemeJSON\":true,\"version\":3}', 'Custom Styles', '', 'inherit', 'closed', 'closed', '', '427-revision-v1', '', '', '2025-04-03 19:23:55', '2025-04-03 17:23:55', '', 427, 'http://localhost/DicoTrav/?p=1499', 0, 'revision', '', 0);
