(363, 'Default', 'Par défaut', 'default', 2, 363, 0),
(364, 'Light', 'Lumineux', 'default', 2, 364, 0),
(365, 'Modern', 'Moderne', 'default', 2, 365, 0),
(366, 'Blue', 'Bleu', 'default', 2, 366, 0),
