INSERT INTO `wp_trp_gettext_fr_fr` (`id`, `original`, `translated`, `domain`, `status`, `original_id`, `plural_form`) VALUES
(1599, 'A logged out user will be redirected to this url If he is not permitted to access the site.', 'Un utilisateur ou une utilisatrice déconnecté·e sera redirigé vers cette URL s’il n’est pas autorisé à accéder au site.', 'ultimate-member', 2, 1599, 0),
(1600, 'Exclude the following URLs', 'Exclure les URL suivantes', 'ultimate-member', 2, 1600, 0),
(1601, 'Here you can exclude URLs beside the redirect URI to be accessible to everyone.', 'Ici, vous pouvez exclure les URL à côté de l’URI de redirection pour qu’ils soient accessibles à tous.', 'ultimate-member', 2, 1601, 0),
(1602, 'Add New URL', 'Ajouter une URL', 'ultimate-member', 2, 1602, 0),
(1603, 'Allow Homepage to be accessible', 'Autoriser l’accès à la page d’accueil', 'ultimate-member', 2, 1603, 0),
(1604, 'Accessible Homepage', 'Page d’accueil accessible', 'ultimate-member', 2, 1604, 0),
(1605, 'Allow Category pages to be accessible', 'Autoriser l’accès aux pages catégorie', 'ultimate-member', 2, 1605, 0),
(1606, 'Accessible Category pages', 'Pages de catégorie accessibles', 'ultimate-member', 2, 1606, 0),
(1607, 'Restricted Post Title', 'Titre de la publication restreinte', 'ultimate-member', 2, 1607, 0),
(1608, 'Replace the restricted Post Title', 'Remplacer le titre de la publication à accès restreint', 'ultimate-member', 2, 1608, 0),
(1609, 'Allow to replace the restricted post title to users that do not have permission to view the content.', 'Autorise le remplacement du titre de la publication restreinte pour les utilisateurs ou utilisatrices qui n’ont pas le droit de voir le contenu.', 'ultimate-member', 2, 1609, 0),
(1610, 'Restricted Access Post Title', 'Titre de la publication à accès restreint', 'ultimate-member', 2, 1610, 0),
(1611, 'If enabled, the text entered below will replace the title of the post/page/CPT for users who do not have permission to view the restricted content. Please see this doc for more information on this.', 'Si cette option est activée, le texte saisi ci-dessous remplacera le titre de la publication/page/CPT pour les utilisateurs/utilisatrices qui n’ont pas le droit de voir le contenu restreint. Veuillez consulter ce document pour plus d’informations à ce sujet.', 'ultimate-member', 2, 1611, 0),
(1612, 'Restricted Access Message', 'Message d’accès restreint', 'ultimate-member', 2, 1612, 0),
(1613, 'This is the message shown to users that do not have permission to view the content.', 'Il s’agit du message affiché aux utilisateurs ou utilisatrices qui n’ont pas le droit de voir le contenu.', 'ultimate-member', 2, 1613, 0),
(1614, 'Restricted Gutenberg Blocks', 'Blocs Gutenberg à accès restreint', 'ultimate-member', 2, 1614, 0),
(1615, 'Enable the \"Content Restriction\" settings for the Gutenberg Blocks', 'Activer les réglages de « Restriction de contenu » pour les blocs Gutenberg', 'ultimate-member', 2, 1615, 0),
(1616, 'If enabled then allows to set the blocks restriction settings in wp-admin.', 'Si cette option est activée, elle autorise la configuration des réglages de restriction des blocs dans wp-admin.', 'ultimate-member', 2, 1616, 0),
(1617, 'Restricted Access Block Message', 'Message du bloc à accès restreint', 'ultimate-member', 2, 1617, 0),
(1618, 'This is the message shown to users that do not have permission to view the block\'s content.', 'Il s’agit du message affiché aux utilisateurs et utilisatrices qui n’ont pas le droit de voir le contenu du bloc.', 'ultimate-member', 2, 1618, 0),
(1619, 'Enable the \"Content Restriction\" settings for post types', 'Activez les réglages de « Restriction de contenu » pour les types de publications', 'ultimate-member', 2, 1619, 0),
(1620, 'Check post types for which you plan to use the \"Content Restriction\" settings.', 'Cochez les types de publications pour lesquels vous prévoyez d’utiliser les réglages de « Restriction de contenu ».', 'ultimate-member', 2, 1620, 0),
(1621, 'Enable the \"Content Restriction\" settings for taxonomies', 'Activer les réglages de « Restriction de contenu » pour les taxonomies', 'ultimate-member', 2, 1621, 0),
(1622, 'Check taxonomies for which you plan to use the \"Content Restriction\" settings.', 'Cochez les taxonomies pour lesquelles vous prévoyez d’utiliser les réglages de « Restriction de contenu ».', 'ultimate-member', 2, 1622, 0),
(1623, 'Custom usermeta table', 'Table personnalisée pour les métadonnées', 'ultimate-member', 2, 1623, 0),
(1624, 'Enable custom table for usermeta', 'Activer l’utilisation d’une table personnalisée pour les métadonnées du compte', 'ultimate-member', 2, 1624, 0),
(1625, 'Check this box if you would like to enable the use of a custom table for user metadata. Improved performance for member directory searches.', 'Cochez cette case si vous souhaitez utiliser une table personnalisée pour les métadonnées du compte. Cela améliore les performances pour les recherches dans le répertoire des membres.', 'ultimate-member', 2, 1625, 0),
(1626, 'We recommend creating a backup of your site before running the update process. Do not exit the page before the update process has complete.', 'Nous vous recommandons de créer une sauvegarde de votre site avant de lancer la mise à jour. Ne quittez pas la page avant que la mise à jour ne soit terminée.', 'ultimate-member', 2, 1626, 0),
(1627, 'After clicking the <strong>\"Run\"</strong> button, the update process will start. All information will be displayed in the field below.', 'Après avoir cliqué sur le bouton <strong>« Exécuter »</strong>, la mise à jour débutera. Toutes les informations seront affichées dans le champ ci-dessous.', 'ultimate-member', 2, 1627, 0),
(1628, 'If the update was successful, you will see a corresponding message. Otherwise, contact technical support if the update failed.', 'Si la mise à jour a réussi, vous verrez un message correspondant. Sinon, contactez le support si la mise à jour a échoué.', 'ultimate-member', 2, 1628, 0),
(1629, 'General', 'Général', 'ultimate-member', 2, 1629, 0),
(1630, 'Pages', '', 'ultimate-member', 0, 1630, 0),
(1631, 'This section enables you to assign a page to one of the core elements necessary for the plugin\'s proper function. The plugin automatically creates and configures the required pages upon installation.<br />You only need to use this tab if you accidentally deleted pages that were automatically created during the initial plugin activation. <a href=\"%s\" target=\"_blank\">Learn more about manually creating pages</a>.', 'Cette section vous permet d’assigner une page à l’un des éléments de cœur nécessaires au bon fonctionnement de l’extension. L’extension crée et configure automatiquement les pages requises lors de l’installation.<br />Vous devez uniquement utiliser cet onglet si vous avez accidentellement supprimé des pages qui ont été créées automatiquement lors de l’activation initiale de l’extension. <a href=\"%s\" target=\"_blank\">En savoir plus sur la création manuelle des pages</a>.', 'ultimate-member', 2, 1631, 0),
(1632, 'Users', 'Utilisateurs/utilisatrices', 'ultimate-member', 2, 1632, 0),
(1633, 'General users settings.', 'Réglages généraux du compte.', 'ultimate-member', 2, 1633, 0),
(1634, 'Registration Default Role', 'Rôle par défaut à l’inscription', 'ultimate-member', 2, 1634, 0),
(1635, 'This will be the role assigned to users registering through Ultimate Member registration forms. By default, this setting will follow the core WordPress setting \"New User Default Role\" unless you specify a different role.', 'Il s’agit du rôle assigné aux utilisateurs/utilisatrices qui s’inscrivent à l’aide des formulaires d’inscription d’Ultimate Member. Par défaut, ce réglage suivra le réglage général de WordPress « Rôle par défaut de tout nouveau compte », à moins que vous ne spécifiiez un rôle différent.', 'ultimate-member', 2, 1635, 0),
(1636, 'Default', 'Par défaut', 'ultimate-member', 2, 1636, 0),
(1637, 'Profile Permalink Base', 'Permalien du profil', 'ultimate-member', 2, 1637, 0),
(1638, 'Here you can control the permalink structure of the user profile URL globally e.g. %s<strong>username</strong>/.', 'Vous pouvez ici contrôler la structure des permaliens de l’URL du profil de l’utilisateur ou utilisatrice, par exemple %s<strong>identifiant</strong>/.', 'ultimate-member', 2, 1638, 0),
(1639, 'Select...', 'Sélectionner…', 'ultimate-member', 2, 1639, 0),
(1640, 'Profile Permalink Base Custom Meta Key', 'Clé méta de base pour le permalien de profil', 'ultimate-member', 2, 1640, 0),
(1641, 'Specify the custom field meta key that you want to use as profile permalink base. Meta value should be unique.', 'Indiquez la clé méta du champ personnalisé que vous souhaitez utiliser comme base du permalien du profil. La valeur méta doit être unique.', 'ultimate-member', 2, 1641, 0),
(1642, 'User Display Name', 'Nom affiché de l’utilisateur/utilisatrice', 'ultimate-member', 2, 1642, 0),
(1643, 'This is the name that will be displayed for users on the front end of your site. Default setting uses first/last name as display name if it exists.', 'Il s’agit du nom qui sera affiché pour les comptes sur l’interface publique du site. Le réglage par défaut utilise le prénom et le nom comme nom affiché s’ils existent.', 'ultimate-member', 2, 1643, 0),
(1644, 'Display Name Custom Field(s)', 'Champ·s personnalisé·s utilisé·s comme nom d’affichage', 'ultimate-member', 2, 1644, 0),
(1645, 'Specify the custom field meta key or custom fields seperated by comma that you want to use to display users name on the frontend of your site.', 'Spécifiez la clé méta du champ personnalisé ou les champs personnalisés séparés par une virgule que vous souhaitez utiliser pour afficher le nom des comptes dans sur l’interface publique de votre site.', 'ultimate-member', 2, 1645, 0),
(1646, 'Hide author pages', 'Masquer les pages des auteurs/autrices', 'ultimate-member', 2, 1646, 0),
(1647, 'Enable author page redirect to user profile', 'Activer la redirection de la page de l’auteur/autrice vers le profil de l’utilisateur/utilisatrice', 'ultimate-member', 2, 1647, 0),
(1648, 'If enabled, author pages will automatically redirect to the user\'s profile page.', 'Si cette option est activée, les pages des auteurs et des autrices seront automatiquement redirigées vers la page de profil du compte.', 'ultimate-member', 2, 1648, 0),
(1649, 'Members Directory', 'Répertoire des membres', 'ultimate-member', 2, 1649, 0),
(1650, 'Enable Members Directory', 'Activer les répertoires des membres', 'ultimate-member', 2, 1650, 0),
(1651, 'Control whether to enable or disable member directories on this site.', 'Permet d’activer ou de désactiver les répertoires des membres sur ce site.', 'ultimate-member', 2, 1651, 0),
(1652, 'Use Gravatar', 'Utiliser Gravatar', 'ultimate-member', 2, 1652, 0),
(1653, 'Enable Gravatar', 'Activer Gravatar', 'ultimate-member', 2, 1653, 0),
(1654, 'Do you want to use Gravatar instead of the default plugin profile photo (If the user did not upload a custom profile photo/avatar)?', 'Souhaitez-vous utiliser Gravatar à la place de la photo de profil par défaut de l’extension (si l’utilisateur ou utilisatrice n’a pas téléversé de photo de profil/avatar personnalisé) ?', 'ultimate-member', 2, 1654, 0),
(1655, 'Use Gravatar builtin image', 'Utiliser l’image intégrée de Gravatar', 'ultimate-member', 2, 1655, 0),
(1656, 'Gravatar has a number of built in options which you can also use as defaults.', 'Gravatar dispose d’un certain nombre d’options intégrées que vous pouvez également utiliser par défaut.', 'ultimate-member', 2, 1656, 0),
(1657, '404 ( File Not Found response )', '404 (réponse fichier non trouvé)', 'ultimate-member', 2, 1657, 0),
(1658, 'Mystery Man', 'Homme mystère', 'ultimate-member', 2, 1658, 0),
(1659, 'Identicon', '', 'ultimate-member', 0, 1659, 0),
(1660, 'Monsterid', 'MonsterID', 'ultimate-member', 2, 1660, 0),
(1661, 'Wavatar', '', 'ultimate-member', 0, 1661, 0),
(1662, 'Retro', 'Rétro', 'ultimate-member', 2, 1662, 0),
(1663, 'Blank ( a transparent PNG image )', 'Vide (une image PNG transparente)', 'ultimate-member', 2, 1663, 0),
(1664, 'Replace Gravatar\'s Default avatar', 'Remplacer l’avatar par défaut de Gravatar', 'ultimate-member', 2, 1664, 0),
(1665, 'Set Default plugin avatar as Gravatar\'s Default avatar', 'Définir l’avatar par défaut de l’extension comme l’avatar par défaut de Gravatar', 'ultimate-member', 2, 1665, 0),
(1666, 'Do you want to use the plugin default avatar instead of the gravatar default photo (If the user did not upload a custom profile photo/avatar).', 'Voulez-vous utiliser l’avatar par défaut de l’extension au lieu de la photo par défaut de Gravatar (si l’utilisateur ou utilisatrice n’a pas téléversé de photo/avatar de profil personnalisé).', 'ultimate-member', 2, 1666, 0),
(1667, 'Delete user comments', 'Supprimer les commentaires d’un utilisateur/utilisatrice', 'ultimate-member', 2, 1667, 0),
(1668, 'Enable deleting user comments after deleting a user', 'Permettre la suppression des commentaires de l’utilisateur/utilisatrice après la suppression d’un compte', 'ultimate-member', 2, 1668, 0),
(1669, 'Do you want to automatically delete a user\'s comments when they delete their account or are removed from the admin dashboard?', 'Souhaitez-vous supprimer automatiquement les commentaires d’un utilisateur ou utilisatrice lorsqu’il·elle supprime son compte ou qu’il·elle est retiré·e du tableau de bord d’administration ?', 'ultimate-member', 2, 1669, 0),
(1670, 'Password & Security settings.', 'Mot de passe et réglages de sécurité.', 'ultimate-member', 2, 1670, 0),
(1671, 'Toggle Password Visibility', 'Permuter la visibilité du mot de passe', 'ultimate-member', 2, 1671, 0),
(1672, 'Enable password show/hide icon on password field', 'Activer l’icône d’affichage/masquage du mot de passe dans le champ du mot de passe', 'ultimate-member', 2, 1672, 0),
(1673, 'Enable users to view their inputted password before submitting the form.', 'Permet aux utilisateurs et utilisatrices de voir le mot de passe qu’ils·elles ont saisi avant d’envoyer le formulaire.', 'ultimate-member', 2, 1673, 0),
(1674, 'Require Strong Passwords', 'Exiger des mots de passe forts', 'ultimate-member', 2, 1674, 0),
(1675, 'Enable strong passwords', 'Activer les mots de passe forts', 'ultimate-member', 2, 1675, 0),
(1676, 'Enable this option to apply strong password rules to all password fields (user registration, password reset and password change).', 'Activez cette option pour appliquer des règles de mot de passe fort à tous les champs de mot de passe (inscription de l’utilisateur/utilisatrice, réinitialisation du mot de passe et changement de mot de passe).', 'ultimate-member', 2, 1676, 0),
(1677, 'Password minimum length', 'Longueur minimale du mot de passe', 'ultimate-member', 2, 1677, 0),
(1678, 'Enter the minimum number of characters a user must use for their password. The default minimum characters is 8.', 'Saisissez le nombre minimum de caractères qu’un utilisateur ou une utilisatrice doit utiliser pour son mot de passe. Le nombre minimum de caractères par défaut est de 8.', 'ultimate-member', 2, 1678, 0),
(1679, 'Password maximum length', 'Longueur maximale du mot de passe', 'ultimate-member', 2, 1679, 0),
(1680, 'Enter the maximum number of characters a user can use for their password. The default maximum characters is 30.', 'Saisissez le nombre maximum de caractères qu’un utilisateur ou une utilisatrice peut utiliser pour son mot de passe. Le nombre maximal de caractères par défaut est de 30.', 'ultimate-member', 2, 1680, 0),
(1681, 'Email activation link expiration (days)', 'Expiration du lien d’activation par e-mail (en jours)', 'ultimate-member', 2, 1681, 0),
(1682, 'For user registrations requiring email confirmation via a link, how long should the activation link remain active before expiring? If this field is left blank, the activation link will not expire.', 'Pour les inscriptions d’utilisateurs ou utilisatrices nécessitant une confirmation par e-mail au moyen d’un lien, combien de temps le lien d’activation doit-il rester actif avant d’expirer ? Si ce champ est laissé vide, le lien d’activation n’expirera jamais.', 'ultimate-member', 2, 1682, 0),
(1683, 'SEO', '', 'ultimate-member', 0, 1683, 0),
(1684, 'SEO settings for the user profiles.', 'Réglages SEO pour les profils d’utilisateur/utilisatrices.', 'ultimate-member', 2, 1684, 0),
(1685, 'Avoid indexing profile by search engines', 'Éviter l’indexation du profil par les moteurs de recherche', 'ultimate-member', 2, 1685, 0),
(1686, 'Hides the profile page for robots. This setting can be overridden by individual role settings.', 'Masque la page de profil pour les robots. Ce réglage peut être remplacé par des réglages de rôle individuels.', 'ultimate-member', 2, 1686, 0),
(1687, 'No', 'Non', 'ultimate-member', 2, 1687, 0),
(1688, 'Yes', 'Oui', 'ultimate-member', 2, 1688, 0),
(1689, 'User Profile Title', 'Titre du profil de l’utilisateur/utilisatrice', 'ultimate-member', 2, 1689, 0),
(1690, 'This is the title that is displayed on a specific user profile.', 'Il s’agit du titre qui s’affiche sur le profil d’un utilisateur ou d’une utilisatrice spécifique.', 'ultimate-member', 2, 1690, 0),
(1691, 'User Profile Dynamic Meta Description', 'Méta-description dynamique du profil de l’utilisateur/utilisatrice', 'ultimate-member', 2, 1691, 0),
(1692, 'This will be used in the meta description that is available for search-engines.', 'Ce texte sera utilisé dans la méta-description destinée aux moteurs de recherche.', 'ultimate-member', 2, 1692, 0),
(1693, 'Main account tab', 'Onglet principal du compte', 'ultimate-member', 2, 1693, 0),
(1694, 'Allows you to control the fields on the main tab of Account page.', 'Vous permet de contrôler les champs de l’onglet principal de la page du compte.', 'ultimate-member', 2, 1694, 0),
(1695, 'Display First & Last name fields', 'Afficher les champs prénom et nom', 'ultimate-member', 2, 1695, 0),
(1696, 'Enable to display First & Last name fields', 'Permet d’afficher les champs prénom et nom', 'ultimate-member', 2, 1696, 0),
(1697, 'If enabled, the First & Last name fields will be shown on the account page.', 'Si cette option est activée, les champs nom et prénom seront affichés sur la page du compte.', 'ultimate-member', 2, 1697, 0),
(1698, 'Disable First & Last name field editing', 'Désactiver la modification des champs prénom et nom', 'ultimate-member', 2, 1698, 0),
(1699, 'Enable to prevent First & Last name editing by users', 'Permet d’empêcher la modification des noms et prénoms par les utilisateurs/utilisatrices', 'ultimate-member', 2, 1699, 0),
(1700, 'If enabled, this feature will prevent users from changing their first and last names on the account page.', 'Si elle est activée, cette fonctionnalité empêchera les utilisateurs ou utilisatrices de modifier leurs prénoms et noms sur la page du compte.', 'ultimate-member', 2, 1700, 0),
(1701, 'Require First & Last Name', 'Prénom et nom obligatoires', 'ultimate-member', 2, 1701, 0),
(1702, 'First and last name fields are required', 'Les champs prénom et nom sont obligatoires', 'ultimate-member', 2, 1702, 0),
(1703, 'If enabled, users will not be allowed to remove their first or last names when updating their account information.', 'Si cette option est activée, les utilisateurs ou utilisatrices ne seront pas autorisés à supprimer leur prénom ou leur nom lors de la mise à jour des informations relatives à leur compte.', 'ultimate-member', 2, 1703, 0),
(1704, 'Allow users to change email', 'Autoriser les utilisateurs et utilisatrices à modifier leur e-mail', 'ultimate-member', 2, 1704, 0),
(1705, 'Enable changing email via the account page', 'Permettre la modification de l’e-mail sur la page du compte', 'ultimate-member', 2, 1705, 0),
(1706, 'If disabled, users will not be allowed to change their email address on the account page.', 'Si cette option est désactivée, les utilisateurs ne seront pas autorisés à modifier leur adresse e-mail sur la page de leur compte.', 'ultimate-member', 2, 1706, 0),
(1707, 'Require password to update account', 'Obligation de fournir un mot de passe pour la mise à jour du compte', 'ultimate-member', 2, 1707, 0),
(1708, 'Enable required password', 'Activer l’obligation de mot de passe', 'ultimate-member', 2, 1708, 0),
(1709, 'If enabled, users will need to enter their password when updating their information via the account page.', 'Si cette option est activée, les utilisateurs ou utilisatrices devront saisir leur mot de passe lorsqu’ils·elles mettront à jour leurs informations sur la page du compte.', 'ultimate-member', 2, 1709, 0),
(1710, 'Change password tab', 'Onglet « Modifier le mot de passe »', 'ultimate-member', 2, 1710, 0),
(1711, 'Enables you to toggle the change password tab on the account page.', 'Permet de permuter l’onglet de modification du mot de passe sur la page du compte.', 'ultimate-member', 2, 1711, 0),
(1712, 'Password Account Tab', 'Onglet « Modifier le mot de passe »', 'ultimate-member', 2, 1712, 0),
(1713, 'Display password change account tab', 'Afficher l’onglet de modification du mot de passe du compte', 'ultimate-member', 2, 1713, 0),
(1714, 'Enable or disable the \"Password\" tab on the account page.', 'Activer ou désactiver l’onglet « Mot de passe » sur la page du compte.', 'ultimate-member', 2, 1714, 0),
(1715, 'Privacy tab', 'Onglet « Confidentialité »', 'ultimate-member', 2, 1715, 0),
(1716, 'Enables you to toggle the privacy tab on the account page. Disable this tab to prevent users from altering their privacy settings.', 'Permet de permuter l’onglet « Confidentialité » sur la page du compte. Désactivez cet onglet pour empêcher les utilisateurs ou utilisatrices de modifier leurs réglages de confidentialité.', 'ultimate-member', 2, 1716, 0),
(1717, 'Privacy Account Tab', 'Onglet « Confidentialité »', 'ultimate-member', 2, 1717, 0),
(1718, 'Display privacy account tab', 'Affichage de l’onglet « Confidentialité » du compte', 'ultimate-member', 2, 1718, 0),
(1719, 'Enable or disable the \"Privacy\" tab on the account page.', 'Activer ou désactiver l’onglet « Confidentialité » sur la page du compte.', 'ultimate-member', 2, 1719, 0),
(1720, 'Allow users to hide their profiles from directory', 'Autoriser les utilisateurs et utilisatrices à masquer leur profil dans le répertoire des membres', 'ultimate-member', 2, 1720, 0),
(1721, 'Enable users ability to alter their profile visibility in member directories', 'Permettre aux utilisateurs/utilisatrices de modifier la visibilité de leur profil dans le répertoire des membres', 'ultimate-member', 2, 1721, 0),
(1722, 'If enabled, this will allow users to change their profile visibility in the member directory from the account page.', 'Si cette option est activée, elle autorisera les utilisateurs à modifier la visibilité de leur profil dans le répertoire des membres à partir de la page de leur compte.', 'ultimate-member', 2, 1722, 0),
(1723, 'Hide profiles from directory by default', 'Masquer les profils du répertoire par défaut', 'ultimate-member', 2, 1723, 0),
(1724, 'Set the default value for the \"Hide my profile from directory\" option.', 'Définir la valeur par défaut pour l’option « Masquer mon profil sur le répertoire ».', 'ultimate-member', 2, 1724, 0),
(1725, 'Notifications tab', 'Onglet « Notifications »', 'ultimate-member', 2, 1725, 0),
(1726, 'Enables you to toggle the notifications tab on the account page. Disable this tab to prevent users from altering their notifications settings.', 'Permet de permuter l’onglet des notifications sur la page du compte. Désactivez cet onglet pour empêcher les utilisateurs ou utilisatrices de modifier leurs réglages concernant les notifications.', 'ultimate-member', 2, 1726, 0),
