(1766, 'Reset Password', 'Réinitialiser le mot de passe', 'ultimate-member', 2, 1766, 0),
(1767, 'Allows to manage reset password settings.', 'Autoriser à gérer les réglages de réinitialisation du mot de passe.', 'ultimate-member', 2, 1767, 0),
