(1890, 'Registration Secondary Button URL', 'URL du bouton secondaire de la page d’inscription', 'ultimate-member', 2, 1890, 0),
(1891, 'You can replace default link for this button by entering custom URL.', 'Vous pouvez remplacer le lien par défaut de ce bouton en saisissant une URL personnalisée.', 'ultimate-member', 2, 1891, 0),
(1892, 'Registration Field Icons', 'Icônes des champs d’inscription', 'ultimate-member', 2, 1892, 0),
