INSERT INTO `wp_trp_gettext_it_it` (`id`, `original`, `translated`, `domain`, `status`, `original_id`, `plural_form`) VALUES
(2431, 'Check this box if you would like to enable the use of a custom table for user metadata. Improved performance for member directory searches.', 'Cochez cette case si vous souhaitez utiliser une table personnalisée pour les métadonnées du compte. Cela améliore les performances pour les recherches dans le répertoire des membres.', 'ultimate-member', 2, 1625, 0),
