(448, 'Store anonymized IP address (remove last 3 digits)', 'download-monitor', 'trp_context', ''),
(449, 'Store no IP address', 'download-monitor', 'trp_context', ''),
(450, 'Count unique IPs only', 'download-monitor', 'trp_context', ''),
(451, 'If enabled, the counter for each download will only increment and create a log entry once per IP address. Note that this option only works if %1$s is set to %2$s.', 'download-monitor', 'trp_context', ''),
