(1024, 'Improve your  website performance by inlining your CSS.', 'easy-table-of-contents', 'trp_context', ''),
(1025, 'Headings:', 'easy-table-of-contents', 'trp_context', ''),
(1026, 'Select the heading to consider when generating the table of contents. Deselecting a heading will exclude it.', 'easy-table-of-contents', 'trp_context', ''),
(1027, 'Heading 1 (h1)', 'easy-table-of-contents', 'trp_context', ''),
(1028, 'Heading 2 (h2)', 'easy-table-of-contents', 'trp_context', ''),
